1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
6	import type {SessionStore} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () =>
55	        answerInTurn(ws, session, orchestrator, sessionStore, validation, signal)
56	      );
57	    }
58	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
59	    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
60	  };
61	}
62	
63	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
64	async function answerInTurn(
65	  ws: WebSocket,
66	  session: ChatSession,
67	  orchestrator: ChatOrchestrator,
68	  sessionStore: SessionStore | undefined,
69	  validation: ValidationResult,
70	  signal: AbortSignal | undefined
71	): Promise<void> {
72	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
73	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
74	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
75	    return;
76	  }
77	  const startedAt = Date.now();
78	  try {
79	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, sessionStore, validation, signal));
80	  } finally {
81	    endTurn(ws, session, signal, startedAt);
82	  }
83	}
84	
85	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
86	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
87	  if (signal?.aborted) {
88	    log.info('message', 'turn abandoned: its socket closed', {
89	      sessionId: session.sessionId,
90	      elapsedMs: Date.now() - startedAt,
91	    });
92	    return;
93	  }
94	  sendStreamEnd(ws);
95	}
96	
97	async function answerUserMessage(
98	  ws: WebSocket,
99	  session: ChatSession,
100	  orchestrator: ChatOrchestrator,
101	  sessionStore: SessionStore | undefined,
102	  validation: ValidationResult,
103	  signal: AbortSignal | undefined
104	): Promise<void> {
105	  const message = validation.valid ? validation.data : undefined;
106	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
107	  await answerFrame(ws, session, validation, sessionStore);
108	}
109	
110	async function answerFrame(
111	  ws: WebSocket,
112	  session: ChatSession,
113	  validation: ValidationResult,
114	  sessionStore: SessionStore | undefined
115	): Promise<void> {
116	  if (!validation.valid) {
117	    log.warn('message', 'validation failed', {error: validation.error});
118	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
119	    return;
120	  }
121	
122	  const message = validation.data;
123	  if (message.type === 'ping') handlePing(ws, message.timestamp);
124	  if (message.type === 'list_sessions') await answerSessionList(ws, session, message, sessionStore);
125	}
126	
127	// The user id is the session's, never a field on the frame: the validator has already dropped one the client sent.
128	async function answerSessionList(
129	  ws: WebSocket,
130	  session: ChatSession,
131	  message: ListSessionsMessage,
132	  sessionStore: SessionStore | undefined
133	): Promise<void> {
134	  try {
135	    const summaries = await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before});
136	    sendSessionList(ws, summaries ?? []);
137	  } catch (error) {
138	    const detail = error instanceof Error ? error.message : 'Unknown error';
139	    log.error('ws', 'listing conversations failed', {
140	      sessionId: session.sessionId,
141	      userId: session.userId,
142	      error: detail,
143	    });
144	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
145	  }
146	}
147	
148	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
149	export function isUserMessageFrame(rawMessage: unknown): boolean {
150	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
151	}
152	
153	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
154	  try {
155	    await action();
156	  } catch (error) {
157	    const message = error instanceof Error ? error.message : 'Unknown error';
158	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
159	    log.error('message', 'handling error', {error: message, code});
160	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
161	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
162	      return;
163	    }
164	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
165	  }
166	}
167	
168	async function handleUserMessage(
169	  ws: WebSocket,
170	  session: ChatSession,
171	  orchestrator: ChatOrchestrator,
172	  content: string,
173	  signal: AbortSignal | undefined
174	): Promise<void> {
175	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
176	
177	  const userEntry = createUserEntry(content);
178	  const userIndex = appendEntry(session, userEntry);
179	  sendUpsert(ws, userIndex, userEntry);
180	
181	  const parser = new ThinkingTagParser();
182	  const state: StreamState = {
183	    thinkingIndex: null,
184	    assistantIndex: null,
185	    suppressOutput: false,
186	    sentAssistantIndices: [],
187	  };
188	
189	  let textChunkCount = 0;
190	
191	  try {
192	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
193	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
194	      if (signal?.aborted) break;
195	      textChunkCount = logChunk(chunk, textChunkCount);
196	      processChunk(ws, session, state, parser, chunk);
197	    }
198	  } finally {
199	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
200	    flushHeldText(ws, session, state, parser);
201	    closeCutOff(ws, session, state, 'thinkingIndex');
202	    closeCutOff(ws, session, state, 'assistantIndex');
203	  }
204	
205	  if (textChunkCount > 0) {
206	    log.debug('stream', `received ${textChunkCount} text chunks`);
207	  }
208	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
209	}
210	
211	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
212	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
213	  if (chunk.type === 'text') return textChunkCount + 1;
214	
215	  if (textChunkCount > 0) {
216	    log.debug('stream', `received ${textChunkCount} text chunks`);
217	  }
218	
219	  if (chunk.type === 'tool_result') {
220	    log.debug('stream', 'tool_result chunk', {
221	      messageCount: chunk.clientMessages.length,
222	      types: chunk.clientMessages.map(m => m.type),
223	    });
224	    return 0;
225	  }
226	
227	  log.debug('stream', 'chunk', {type: chunk.type});
228	  return 0;
229	}
230	
231	function processChunk(
232	  ws: WebSocket,
233	  session: ChatSession,
234	  state: StreamState,
235	  parser: ThinkingTagParser,
236	  chunk: MessageChunk
237	): void {
238	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
239	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
240	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
241	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
242	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
243	}
244	
245	function processTextChunk(
246	  ws: WebSocket,
247	  session: ChatSession,
248	  state: StreamState,
249	  parser: ThinkingTagParser,
250	  text: string
251	): void {
252	  const segments = parser.push(text);
253	  for (const segment of segments) {
254	    handleTextSegment(ws, session, state, segment);
255	  }
256	}
257	
258	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
259	  if (segment.type === 'thinking') {
260	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
261	    return;
262	  }
263	  commitAndClear(ws, session, state, 'thinkingIndex');
264	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
265	}
266	
267	function streamSegment(
268	  ws: WebSocket,
269	  session: ChatSession,
270	  state: StreamState,
271	  key: StateIndexKey,
272	  createEntry: EntryFactory,
273	  content: string
274	): void {
275	  const isNew = initSegment(session, state, key, createEntry);
276	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
277	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
278	  appendDelta(session, state[key]!, content);
279	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
280	}
281	
282	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
283	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
284	  markSuppressed(session, index);
285	  sendSkip(ws, index);
286	}
287	
288	function markSuppressed(session: ChatSession, index: number): void {
289	  const entry = session.entries[index];
290	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
291	}
292	
293	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
294	  if (state[key] !== null) return false;
295	  state[key] = appendEntry(session, createEntry());
296	  return true;
297	}
298	
299	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
300	  const index = state[key];
301	  if (index === null) return;
302	
303	  commitEntry(session, index);
304	  state[key] = null;
305	
306	  // Only what the client received can be retracted, and only assistant entries.
307	  if (state.suppressOutput) return;
308	
309	  sendCommit(ws, index);
310	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
311	}
312	
313	function processToolUseChunk(
314	  ws: WebSocket,
315	  session: ChatSession,
316	  toolCall: {name: string; input: Record<string, unknown>}
317	): void {
318	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
319	  const toolIndex = appendEntry(session, toolEntry);
320	  sendUpsert(ws, toolIndex, toolEntry);
321	}
322	
323	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
324	  for (const msg of clientMessages) {
325	    log.debug('stream', 'forwarding client message to frontend', {
326	      type: msg.type,
327	      index: 'index' in msg ? msg.index : undefined,
328	    });
329	    sendJson(ws, msg);
330	  }
331	}
332	
333	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
334	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
335	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
336	  commitOpenEntries(ws, session, state);
337	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
338	
339	  for (const idx of state.sentAssistantIndices) {
340	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
341	    markSuppressed(session, idx);
342	  }
343	
344	  state.sentAssistantIndices = [];
345	  state.suppressOutput = true;
346	}
347	
348	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
349	  flushHeldText(ws, session, state, parser);
350	  commitOpenEntries(ws, session, state);
351	}
352	
353	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
354	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
355	  for (const segment of parser.flush()) {
356	    handleTextSegment(ws, session, state, segment);
357	  }
358	}
359	
360	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
361	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
362	  const index = state[key];
363	  if (index === null) return;
364	  markTruncated(session, index);
365	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
366	  commitAndClear(ws, session, state, key);
367	}
368	
369	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
370	  commitAndClear(ws, session, state, 'thinkingIndex');
371	  commitAndClear(ws, session, state, 'assistantIndex');
372	}
373	
374	function handlePing(ws: WebSocket, timestamp: number): void {
375	  ws.send(JSON.stringify({type: 'pong', timestamp}));
376	}
377

