1	import {WebSocket, WebSocketServer} from 'ws';
2	import {IncomingMessage} from 'http';
3	import {Duplex} from 'stream';
4	import {v4 as uuidv4} from 'uuid';
5	import type {WsAuthenticator} from '../../types/auth.js';
6	import type {SessionStore} from '../../types/sessionStore.js';
7	import type {ConnectedMessage} from '../../types/messages.js';
8	import type {AuthenticatedUser, ChatSession} from '../../types/session.js';
9	import {ErrorCodes} from '../../types/session.js';
10	import {sendError} from './sender.js';
11	import {isUserMessageFrame} from './messageHandler.js';
12	import {isValidWsPath, rejectSocket, parseWsData, sessionIdFromUpgrade, newSessionRequested} from './helpers.js';
13	import {credentialFromSubprotocol} from './subprotocol.js';
14	import {replayEntries, resumableSession, resumeFields} from './sessionResume.js';
15	import type {ConnectInfo, SessionResumeOptions} from './sessionResume.js';
16	import {log} from '../../shared/logger.js';
17	
18	export interface ExtWebSocket extends WebSocket {
19	  isAlive: boolean;
20	  userId: string | number;
21	  workspaceId?: string | number;
22	  authHeaders?: {
23	    cookie?: string;
24	    authorization?: string;
25	    host?: string;
26	  };
27	  requestedSessionId?: string;
28	  startNewSession?: boolean;
29	}
30	
31	export interface ConnectionHandlerDeps {
32	  wsAuth: WsAuthenticator;
33	  sessionStore: SessionStore;
34	  /** `signal` is the connection's own, aborted when its socket closes (specs/hal-engine-abandon-on-close/spec.md). */
35	  handleMessage: (
36	    ws: WebSocket,
37	    session: import('../../types/session.js').ChatSession,
38	    rawMessage: unknown,
39	    signal?: AbortSignal
40	  ) => Promise<void>;
41	  basePath: string;
42	  onConnect?: (session: import('../../types/session.js').ChatSession, connection: ConnectInfo) => void | Promise<void>;
43	  onDisconnect?: (sessionId: string) => void | Promise<void>;
44	  resume?: SessionResumeOptions;
45	}
46	export function createUpgradeHandler(wss: WebSocketServer, deps: ConnectionHandlerDeps) {
47	  return function handleUpgrade(request: IncomingMessage, socket: Duplex, head: Buffer): void {
48	    // Nothing may throw out of this listener: the `upgrade` event has no catch above it, so a throw ends the process.
49	    if (!request.headers.host || !isValidWsPath(request.url || '', deps.basePath)) {
50	      rejectSocket(socket, '400 Bad Request');
51	      return;
52	    }
53	
54	    authenticate(deps.wsAuth, request)
55	      .then(user => {
56	        if (!user) {
57	          rejectSocket(socket, '401 Unauthorized');
58	          return;
59	        }
60	
61	        wss.handleUpgrade(request, socket, head, ws => {
62	          const extWs = ws as ExtWebSocket;
63	          extWs.userId = user.id;
64	          extWs.workspaceId = user['workspaceId'] as string | number | undefined;
65	          extWs.authHeaders = {
66	            cookie: request.headers.cookie,
67	            authorization: request.headers.authorization || bearerFromWebSocketProtocol(request),
68	            host: (request.headers['x-forwarded-host'] as string | undefined) ?? request.headers.host,
69	          };
70	          extWs.isAlive = true;
71	          if (deps.resume?.enabled) {
72	            extWs.requestedSessionId = sessionIdFromUpgrade(request.url || '', deps.basePath);
73	            extWs.startNewSession = newSessionRequested(request.url || '', deps.basePath);
74	          }
75	          wss.emit('connection', extWs, request);
76	        });
77	      })
78	      .catch((error: unknown) => {
79	        // The type alone: an authenticator's message can carry the credential it was checking.
80	        log.error('ws', 'authenticator failed', {errorType: error instanceof Error ? error.name : typeof error});
81	        rejectSocket(socket, '500 Internal Server Error');
82	      });
83	  };
84	}
85	
86	// Async, so a synchronous throw becomes a rejection (answered 500) and a user returned without a promise still resolves.
87	async function authenticate(wsAuth: WsAuthenticator, request: IncomingMessage): Promise<AuthenticatedUser | null> {
88	  return wsAuth(request);
89	}
90	
91	function bearerFromWebSocketProtocol(req: IncomingMessage): string | undefined {
92	  const token = credentialFromSubprotocol(req.headers['sec-websocket-protocol']);
93	  return token ? `Bearer ${token}` : undefined;
94	}
95	
96	export function createConnectionHandler(deps: ConnectionHandlerDeps, examplePrompts: string[]) {
97	  return function handleConnection(ws: ExtWebSocket): void {
98	    // The listener stays synchronous: an async one rejects into the emitter, and node ends the process on that.
99	    openSession(deps, examplePrompts, ws).catch((error: unknown) => {
100	      log.error('ws', 'connection setup failed', {error: messageOf(error)});
101	      // Resumed before closing: a paused socket never reads the close frame it would be waiting for.
102	      ws.resume();
103	      ws.close(1011, 'Connection setup failed');
104	    });
105	  };
106	}
107	
108	// The sockets open on each session, oldest first: a resumed session can be open on more than one at once.
109	const openSockets = new WeakMap<ChatSession, ExtWebSocket[]>();
110	
111	async function openSession(deps: ConnectionHandlerDeps, examplePrompts: string[], ws: ExtWebSocket): Promise<void> {
112	  // A requested id is never adopted for a new session: that would be session fixation.
113	  let sessionId = uuidv4();
114	  const state = {closed: false, settled: false, notified: false, delivered: false};
115	  const held: {session?: ChatSession; socket: ExtWebSocket} = {socket: ws};
116	  // One per connection, not per message or session: a close abandons the turn in flight and every message queued behind it.
117	  const connection = new AbortController();
118	
119	  ws.on('error', (error: Error) => {
120	    log.error('ws', 'connection error', {sessionId, error: error.message});
121	  });
122	
123	  ws.on('pong', () => {
124	    ws.isAlive = true;
125	  });
126	
127	  ws.on('close', () => {
128	    // First, so the turn stops before the session is torn down and before onDisconnect.
129	    connection.abort();
130	    state.closed = true;
131	    log.info('ws', 'disconnected', {sessionId});
132	    if (state.settled) endSession(deps, sessionId, state, held);
133	  });
134	
135	  // Paused across the await so a frame arriving before the message listener exists is buffered, not dropped.
136	  ws.pause();
137	
138	  const outcome = await resumableSession(deps.sessionStore, ws, deps.resume);
139	  const resumed = outcome.session;
140	  if (resumed) sessionId = resumed.sessionId;
141	  const session = resumed ?? (await createSession(deps, sessionId, ws));
142	  state.settled = true;
143	
144	  if (session === undefined) {
145	    // Resumed before closing: ws.close() on a paused socket waits for a close frame it can never read.
146	    ws.resume();
147	    ws.close(1011, 'Session store unavailable');
148	    return;
149	  }
150	
151	  // A new session is this socket's from the start; a resumed one only once this socket is known to be open.
152	  if (!resumed) join(session, ws);
153	
154	  if (state.closed) {
155	    // Held first: a store that implements no evict still holds this session, and it carries the caller's credentials.
156	    held.session = session;
157	    await evictUnlessResumed(deps, sessionId, resumed);
158	    endSession(deps, sessionId, state, held);
159	    ws.resume();
160	    return;
161	  }
162	
163	  if (resumed) join(resumed, ws);
164	  held.session = session;
165	
166	  log.info('ws', 'connected', {sessionId, userId: ws.userId});
167	
168	  const connected: ConnectedMessage = {
169	    type: 'connected',
170	    sessionId,
171	    message: 'Connected to HAL Engine',
172	    examplePrompts,
173	    ...resumeFields(deps.resume, outcome),
174	  };
175	  // A socket that died between the check above and this frame must not leave the session it was created for behind.
176	  try {
177	    ws.send(JSON.stringify(connected));
178	    if (resumed) replayEntries(ws, resumed);
179	  } catch (error) {
180	    log.error('ws', 'connected frame failed', {sessionId, error: messageOf(error)});
181	    await evictUnlessResumed(deps, sessionId, resumed);
182	    endSession(deps, sessionId, state, held);
183	    ws.resume();
184	    ws.close(1011, 'Connection setup failed');
185	    return;
186	  }
187	
188	  state.delivered = true;
189	
190	  // Deferred, not inline: a synchronous throw in the `connection` listener corrupts an already-upgraded socket.
191	
192	  // A microtask, not setImmediate: it drains before the loop delivers any inbound frame on this socket.
193	  queueMicrotask(() =>
194	    runHook('onConnect', sessionId, () => deps.onConnect?.(session, {resumed: resumed !== undefined}))
195	  );
196	
197	  // Off-lock frames still dispatch one answer at a time, in arrival order, so a pipelined ping reads session_list first; a turn does not join this chain — the lock orders turns, and a ping must not wait behind one.
198	  let dispatched: Promise<void> = Promise.resolve();
199	  ws.on('message', (frame: Buffer | string) => {
200	    const parsed = parseWsData(frame);
201	    if (parsed === null) {
202	      sendError(ws, ErrorCodes.INVALID_FORMAT, 'Invalid JSON');
