import type {AddressInfo} from 'node:net';
import type {WebSocket} from 'ws';
import {startEngineWith, connectClient, stopEngines, delegatingStore} from './wsTestSupport.js';
import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
import {setLogger} from '../../shared/logger.js';

// The acceptance suite drives this seam over a real socket; here it is at unit scope, so the upgrade,
// the wiring and the ordered answers are observable without it.

interface Frame {
  type: string;
  sessions?: unknown;
  code?: string;
}

interface Ask {
  frames: Frame[];
}

const ask = async (url: string, outbound: Record<string, unknown>): Promise<Ask> => {
  const client = connectClient(url);
  const frames: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      if (frame.type !== 'connected') frames.push(frame);
      else {
        client.send(JSON.stringify(outbound));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      }
    });
  });
  return {frames};
};

const summary = (sessionId: string): SessionSummary => ({
  sessionId,
  createdAt: new Date('2026-01-01T00:00:00.000Z'),
  updatedAt: new Date('2026-01-01T00:02:00.000Z'),
  entryCount: 2,
});

describe('list_sessions over a real upgrade', () => {
  beforeEach(() => {
    setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
  });

  afterEach(async () => {
    await stopEngines();
    setLogger();
  });

  it('answers the connection user, session_list before pong', async () => {
    const seen: Array<{userId: string | number; options: unknown}> = [];
    const store: SessionStore = {
      ...delegatingStore(new InMemorySessionStore()),
      listFor: (userId, options) => {
        seen.push({userId, options});
        return [summary('s9')];
      },
    };
    const {url, hal} = await startEngineWith({sessionStore: store});
    const port = (hal.server.address() as AddressInfo).port;
    expect(port).toBeGreaterThan(0);

    const {frames} = await ask(url, {
      type: 'list_sessions',
      limit: 5,
      before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'},
      userId: 'u2',
    });

    expect(frames).toEqual([
      {
        type: 'session_list',
        sessions: [
          {
            sessionId: 's9',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-01T00:02:00.000Z',
            entryCount: 2,
          },
        ],
      },
    ]);
    expect(seen).toEqual([
      {userId: 'u1', options: {limit: 5, before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'}}},
    ]);
  });

  it('answers an empty list without listFor and SERVER_ERROR when listFor fails', async () => {
    const bare = await startEngineWith({sessionStore: delegatingStore(new InMemorySessionStore())});
    const failing = await startEngineWith({
      sessionStore: {
        ...delegatingStore(new InMemorySessionStore()),
        listFor: () => Promise.reject(new Error('database offline')),
      },
    });

